param([object]$RawEvidence,[object]$Analysis,[string]$Output,[int]$Hours=72)
$ErrorActionPreference='Stop'
$utf8=New-Object Text.UTF8Encoding($true)
$raw=$RawEvidence;$a=$Analysis
function E($v){[Net.WebUtility]::HtmlEncode([string]$v)}
function T($v){try{$dt=if($v -is [datetime] -or $v -is [datetimeoffset]){[datetimeoffset]$v}else{[datetimeoffset]::Parse([string]$v)};$dt.ToOffset([timespan]::FromHours(8)).ToString('yyyy-MM-dd HH:mm:ss')}catch{[string]$v}}
function Short($v,$n=230){$s=([string]$v -replace '\s+',' ').Trim();if($s.Length -gt $n){$s.Substring(0,$n)+'…'}else{$s}}
function SaveText($name,$s){[IO.File]::WriteAllText((Join-Path $Output $name),$s,$utf8)}
function Row($label,$value){if([string]$value){'<div class="row"><dt>'+(E $label)+'</dt><dd>'+(E $value)+'</dd></div>'}}
function Section($id,$n,$title,$content){'<section id="'+$id+'"><h2><span>'+$n+'</span>'+$title+'</h2>'+$content+'</section>'}
$planPath=Join-Path $Output 'response-plan.json'
if(Test-Path -LiteralPath $planPath){$plan=Get-Content -Raw -LiteralPath $planPath -Encoding UTF8|ConvertFrom-Json}else{$plan=& (Get-IRScript 'triage.ps1') -RawEvidence $raw -Analysis $a -Output $Output;SaveText 'response-plan.json' (ConvertTo-Json $plan -Depth 14)}
$cases=@($plan.Cases|Sort-Object @{e={if($_.AutoInvestigation){0}elseif($_.Kind -eq '异常启动轨迹'){1}elseif($_.Kind -eq '内存异常'){1}elseif($_.Severity -eq '高'){2}else{3}}},@{e={$_.EvidenceRank};Descending=$true},Id)
$historicalCases=@($cases|Where-Object ContextOnly)
$cases=@($cases|Where-Object {!$_.ContextOnly})
function GetCaseLevel($c){
 # A high-priority finding or a verified runtime/persistence/communication combination warrants red risk.
 if($c.Severity -eq '高' -or ($c.RuntimeCase -and [int]$c.EvidenceRank -ge 100 -and @($c.Persistence|Where-Object {$_.Enabled -eq $true}).Count -and @($c.NetworkEvidence|Where-Object {$_.Identity -and $_.Value}).Count)){return 'red'}
 return 'yellow'
}
$severeCases=@($cases|Where-Object {(GetCaseLevel $_) -eq 'red'})
$cases=@($cases|Sort-Object @{e={if((GetCaseLevel $_) -eq 'red'){0}else{1}}},@{e={$_.EvidenceRank};Descending=$true},Id)
$materialGaps=New-Object 'Collections.Generic.List[string]'
if(!$raw.Host.Admin){$materialGaps.Add('未以管理员权限检查')}
if(!@($raw.Processes).Count){$materialGaps.Add('未取得进程清单')}
if(!@($raw.Memory).Count){$materialGaps.Add('未取得内存检查记录')}
$required=@('进程','实时网络与进程身份观察','加载模块','进程内存','服务','注册表持久化','计划任务','启动目录','WMI永久订阅','启动目标与全部已加载模块验证','深度文件与网络线索','运行实例与外联追查')
foreach($module in $required){$entry=@($a.Coverage|Where-Object Module -eq $module|Select-Object -Last 1);if(!$entry.Count -or $entry[0].Status -ne '成功'){$materialGaps.Add($module+'未完成')}}
foreach($entry in @($a.Coverage|Where-Object {$_.Status -eq '不可用/不完整' -and $_.Module -notmatch '^Sysmon'})){if(!$materialGaps.Contains($entry.Module+'未完成')){$materialGaps.Add($entry.Module+'未完成')}}
if(@($raw.Processes|Where-Object {!$_.Path -and $_.Pid -notin @(0,4)}).Count){$materialGaps.Add('部分进程路径未取得')}
if(@($a.Coverage|Where-Object {$_.Module -match '^(注册表|模块 PID)' -and $_.Status -ne '成功'}).Count){$materialGaps.Add('部分注册表或模块未读到')}
if(@($a.Files|Where-Object {$_.Signature -in @('未检查','证据未提供','UnknownError') -or !$_.Signature}).Count){$materialGaps.Add('部分候选文件未完成验签')}
if(@($raw.Memory|Where-Object {$_.Opened -and (!$_.Complete -or !$_.IdentityMatched -or $_.ReadFailures -or $_.ThreadFailures)}).Count){$materialGaps.Add('部分进程内存未完整读取')}
if(@($raw.Memory|Where-Object {!$_.Opened -and $_.Pid -notin @(0,4)}).Count){$materialGaps.Add('部分进程内存不可访问')}
$networkCheck=Join-Path $Output 'network-evidence.json'
if(Test-Path -LiteralPath $networkCheck){$nc=[IO.File]::ReadAllText($networkCheck)|ConvertFrom-Json;if($nc.Observation.TraceStatus -ne '完成'){$materialGaps.Add('实时网络观察未完整完成')}}else{$materialGaps.Add('缺少实时网络观察结果')}
$assessmentLevel=if($severeCases.Count){'red'}elseif($cases.Count -or $materialGaps.Count){'yellow'}else{'green'}
$assessmentLabel=switch($assessmentLevel){'red'{'严重风险'}'yellow'{if($cases.Count){'中等异常'}else{'检查不完整'}}'green'{'健康'}}
$assessmentColor=switch($assessmentLevel){'red'{'#c83a43'}'yellow'{'#a66b00'}'green'{'#16805c'}}
$diagnostics=@($plan.Diagnostics | Where-Object Title -eq '历史检测处置状态待确认')
$gaps=New-Object 'Collections.Generic.List[object]'
function G($area,$fact,$impact){$gaps.Add([pscustomobject]@{Area=$area;Fact=$fact;Impact=$impact})}
if(!$raw.Host.Admin){G '权限' '本次以普通权限采集。' '其他用户和系统进程、部分注册表可能读不到；先用管理员权限复采。'}
$np=@($raw.Processes|Where-Object {!$_.Path}).Count
if($np){G '进程身份' ("$np / $(@($raw.Processes).Count) 个进程没有读到程序路径。") '这些进程无法按文件路径完成哈希、签名及启动项关联。'}
foreach($name in @('Sysmon日志','Security日志')){
 $c=@($a.Coverage|Where-Object Module -eq $name|Select-Object -Last 1)
 if(!$c.Count){G $name '证据包没有提供该项采集状态。' '无法评估历史执行与登录行为的覆盖范围。'}
 elseif($c[0].Status -ne '成功'){G $name '未成功取得日志。' $(if($name -eq 'Sysmon日志'){'无法依靠它追溯谁启动进程、写文件或发起连接；管理员重跑不能补回未记录的历史。'}else{'缺少该日志的历史登录、进程创建和配置变更证据。'})}
 elseif([int]$c[0].Count -eq 0){G $name '本次查询返回 0 条匹配事件。' '没有记录可用于历史关联；原因可能是审计配置、时间范围或访问条件，不能解读为未发生入侵。'}
}
foreach($c in @($a.Coverage|Where-Object {$_.Status -eq '不可用/不完整' -and $_.Module -notin @('Sysmon日志','Security日志')})){G $c.Module '本模块采集未完整完成。' '相关结论存在盲区；原始错误保留在 analysis.json 的 Coverage 字段。'}
$total=@($a.Files).Count;$hashed=@($a.Files|Where-Object SHA256).Count
$notSignedCheck=@($a.Files|Where-Object {$_.Signature -in @('未检查','证据未提供') -or !$_.Signature}).Count
if($total -gt $hashed -or $notSignedCheck){G '文件校验' ("$total 个候选文件中，$hashed 个有哈希；$notSignedCheck 个未完成验签。") '受文件大小、数量预算和访问条件限制。没有哈希或没有验签结果的文件，仍然是未知。'}
$search=@($a.Coverage|Where-Object Module -eq '文件搜索预算'|Select-Object -Last 1)
if($search.Count){G '文件范围' (Short $search[0].Detail 230) '这是有限目录的抽查；更深目录、其他磁盘或较早落地文件可能漏掉。'}
$deepSearch=@($a.Coverage|Where-Object Module -eq '深度文件范围'|Select-Object -Last 1)
if($deepSearch.Count){G '深度文件范围' $deepSearch[0].Detail '上面的近期文件抽查与本项深度扫描是两个独立范围；仍未检查的目录及内容不能当作正常。'}
$critical=@($a.Coverage|Where-Object Module -eq '关键对象验证'|Select-Object -Last 1)
if($critical.Count){G '关键启动和加载对象验证' $critical[0].Detail '启动配置、已加载模块已独立验证；这不等于签名正常的软件得到授权，也不覆盖已消失的载荷。'}
$denied=@($a.Coverage|Where-Object {$_.Module -match '^(注册表|模块 PID|目录 )' -and $_.Status -ne '成功'}).Count
if($denied){G '局部读取失败' ("$denied 项注册表、目录或模块读取受限/对象已变化。") '成功完成一个采集模块，不表示该模块下所有对象都已读到。'}
G '深度取证' '内存检查非映像PE、线程起点及主映像首个可执行节最多64KiB；未检查内核、离线磁盘或完整应用日志。' '短小代码补丁、其他节、无头shellcode或已退出载荷仍可能漏报；正常热补丁与解包也可能产生内存差异。'
$memoryRows=@($raw.Memory);$memoryIncomplete=@($memoryRows|Where-Object {!$_.Opened -or !$_.Complete -or !$_.IdentityMatched -or $_.ReadFailures -or $_.ThreadFailures}).Count
if($memoryRows.Count){G '内存覆盖' ("检查 $($memoryRows.Count) 个进程，$memoryIncomplete 个存在访问失败、局部未读或身份变化。") '只报告取得的证据，未读区域不能视为正常。'}else{G '内存覆盖' '没有取得进程内存检查记录。' '缺少该维度不能排除注入。'}
foreach($g in @($a.Coverage|Where-Object {$_.Module -match '内存预算|文件变更日志|启动历史' -and $_.Status -ne '成功'})){G $g.Module (Short $g.Detail 240) '相关历史或内存可能未覆盖。'}
foreach($g in @($a.Coverage|Where-Object {$_.Module -like '安装*' -and $_.Status -ne '成功'})){G $g.Module (Short $g.Detail 260) '超出范围、缺失或不可读取的对象不能判定正常。'}
$sample=$raw.Host.Mode -match '合成'
$stamp=T $raw.Host.TimeUtc
$title=if($cases.Count){"找到 $($cases.Count) 个需要继续核查的对象"}else{'这次没有定位到明确的恶意对象'}
$lead=if($cases.Count){'下面列出触发原因、具体位置和第一步核验。优先级代表先查谁，尚未确认感染或恶意家族。'}else{'目前不能据此判断电脑安全，也没有足够依据指定要处置的恶意文件、注册表值或服务。'}
$packageCases=@($cases|Where-Object Kind -eq '异常安装链')
if($packageCases.Count){
 $abnormalCount=@($packageCases|ForEach-Object {$_.AbnormalFiles}).Count
 $title="发现 $($packageCases.Count) 条异常安装链，$abnormalCount 个高风险落地文件"
 $lead='自动找到安装器关联的异常文件；下面直接列出位置、原因和关联启动配置。没有证据的执行过程与权限维持方式会明确写未知。'
}
$traceCases=@($cases|Where-Object Kind -eq '异常启动轨迹');$memoryCases=@($cases|Where-Object Kind -eq '内存异常')
if($traceCases.Count -or $memoryCases.Count){$title="发现 $($cases.Count) 组异常：启动轨迹 $($traceCases.Count)，内存 $($memoryCases.Count)，其他 $($cases.Count-$traceCases.Count-$memoryCases.Count)";$lead='先看启动、删除和崩溃的实际时间线，以及当前内存证据。时间相近只证明关联线索，不自动认定注入因果或木马家族。'}
$autoCases=@($cases|Where-Object AutoInvestigation)
if($autoCases.Count){$title="发现 $($cases.Count) 组异常，其中 $(@($cases|Where-Object RuntimeCase).Count) 组来自运行实例与通信行为";$lead='按异常对象查看依据、落地位置和精确驻留配置。正常项不展示；配置引用、历史事件和当前运行状态分别标明。'}
$next=New-Object 'Collections.Generic.List[object]'
if(!$raw.Host.Admin){$next.Add([pscustomobject]@{Title='先补一次管理员采集';Text='打开 YingJiLite.exe，点“管理员启动”，在新窗口点“一键检查”。先看新报告的检查盲区是否减少。'})}
if($cases.Count){$next.Add([pscustomobject]@{Title='优先处理已定位的异常对象';Text='保持受影响主机隔离；不要再次运行列出的异常安装器或落地文件。下方给出具体文件及直接关联的启动配置，原始证据已自动保留。'})}
else{$next.Add([pscustomobject]@{Title='仍有异常时，带着具体线索重查';Text='检查下方采集缺口；可将回溯范围改为7天再检查。规则没有命中不能排除感染，必要时补充内存或离线磁盘检查。'})}
$next.Add([pscustomobject]@{Title=if($cases.Count){'确认恶意后再形成处置单'}else{'没有告警或持续异常时，保留这次记录'};Text=if($cases.Count){'以已确认恶意的文件和配置为单位处置，并复查是否重新出现。关联宿主、服务账号和同实例外联只是事实，不能整批当作木马或C2。'}else{'这份报告作为首轮排查记录。失效任务、过去的防护变化，以及“0个命中”都不能单独作为清理或安全结案依据。'}})
if($packageCases.Count){
 $autoCases=@($cases|Where-Object AutoInvestigation)
if($autoCases.Count){$title="发现 $($cases.Count) 组异常，其中 $(@($cases|Where-Object RuntimeCase).Count) 组来自运行实例与通信行为";$lead='按异常对象查看依据、落地位置和精确驻留配置。正常项不展示；配置引用、历史事件和当前运行状态分别标明。'}
$next=New-Object 'Collections.Generic.List[object]'
 $next.Add([pscustomobject]@{Title='保持隔离，避免再次运行关联程序';Text='异常对象与历史记录已定位。报告目录保留原始证据；系统宿主或时间相近的事件不会仅凭关联进入清理清单。'})
 $next.Add([pscustomobject]@{Title='按上方精确位置处理，再复扫';Text='人工处置对象见异常文件及其直接引用配置。没有关联启动项时，不指定其他软件服务或注册表项作为清理目标。处置后重新检查这些位置是否仍存在或重新出现。'})
}
$diagnosticHtml='';$diagnosticDetails='';$mdDiag=''
foreach($d in $diagnostics){
 $human=if($d.Title -eq '失效启动配置'){if($d.Location -match '值/名称=(.+)$'){$matches[1]+'：找不到启动目标'}else{'一个启动配置找不到目标程序'}}elseif($d.Title -eq '历史防护/审计状态' -and $d.Location -match 'Windows Defender'){'Windows 防护曾关闭，采集时状态见下方'}else{$d.Title}
 $displayLocation=if($d.Location -match '^(.*) UTC=(.+)$'){$matches[1]+' | '+(T $matches[2])+' UTC+8'}else{$d.Location}
 $body='<article class="note-card"><h3>'+(E $human)+'</h3><p>'+(E $d.Fact)+'</p><details><summary>具体位置与后续核查</summary><dl>'+(Row '记录位置' $displayLocation)+(Row '指向目标' $d.Target)+'</dl><p class="small">'+(E $d.Next)+'</p></details></article>'
 $diagnosticHtml+=$body
 $diagnosticDetails+=$body+'<pre><code>'+(E $d.Command)+'</code></pre>'
 $mdDiag+="`r`n- **$human**：$($d.Fact)`r`n  位置：$($d.Location)`r`n  目标：$($d.Target)`r`n"
}
function Explain($case){
 if($case.Kind -eq '侧加载候选'){return '有效签名程序加载了同目录未验证DLL，并出现隐藏目录或签名摘要不符。具体依据见证据；不直接推断木马家族。'}
 if($case.Trigger -match 'Office拉起'){return 'Office 进程疑似启动了脚本解释器。要核对文档来源和命令内容；宏、插件或授权自动化也可能触发。'}
 if($case.Trigger -match '挖矿'){return '命令或日志出现挖矿参数。先核对是否为你授权的程序，再查启动来源和关联连接。'}
 if($case.Trigger -match '用户指定'){return '这是你指定追查的对象。工具列出关联证据；指定本身不表示有毒。'}
 if($case.Trigger -match 'IOC'){return '命中你提供的比对指标。需要核实指标来源、时效以及此对象是否确实与告警一致。'}
 if($case.Trigger -match '脚本下载|编码执行'){return '命令或日志出现下载、编码执行等需要核实的行为。先阅读完整命令和事件；运维脚本也可能命中。'}
 return '该对象触发了待核实规则。先对照下面的原始依据，核对业务用途和执行来源。'
}
$cards='';$allCards='';$deep='';$mdCases='';$viewFindings=@()
foreach($c in $cases){
 if($c.Id -notmatch '^C\d+$'){throw 'Invalid case id'}
 if($c.AutoInvestigation){
  $facts='<dl>'+(Row '异常对象' $c.Target)+(Row '判断依据' ($c.Trigger -join '；'))+(Row '当前状态' $c.State)+'</dl>'
  foreach($s in $c.Persistence){
   $kind=switch($s.Kind){'Task'{'计划任务'}'Service'{'服务'}'Driver'{'驱动'}'Startup'{'启动目录'}default{'注册表'}}
   $state=if($null -eq $s.Enabled){'启用状态未取得'}elseif($s.Enabled){'已启用'}else{'已禁用'}
   $mode=switch($s.StartMode){'Auto'{'自动启动'}'Manual'{'按需启动'}'Boot'{'引导加载'}'System'{'系统加载'}default{''}}
   $facts+='<dl>'+(Row ($kind+'位置') ($s.Location+' ['+$s.Name+']'))+(Row '执行命令' $s.Command)+(Row '配置状态' (($state+' '+$mode).Trim()))+(Row '配置账号' $s.Principal)+(Row '触发与运行级别' ($s.Triggers+' / '+$s.RunLevel))+(Row '任务文件' $s.TaskFile)+(Row '任务注册表索引' $s.RegistryTree)+(Row '任务注册表对象' $s.RegistryTask)+'</dl>'
  }
  if(!$c.Persistence.Count){$facts+='<p class="small">权限维持：本次未找到直接关联配置。</p>'}
  foreach($n in @($c.NetworkEvidence|Select-Object -First 6)){$facts+='<dl>'+(Row '通信 / 地址线索' $n.Value)+(Row '进程与依据' ($n.Process+' | '+$n.Identity+' | '+$n.Kind))+(Row '判读' $n.Assessment)+'</dl>'}
  $card='<article class="case"><div class="case-title"><span class="badge">'+(E $c.Id)+'</span><h3>'+(E $c.Kind)+'</h3><span class="priority">'+(E $c.Severity)+'优先级</span></div>'+$facts+'<details><summary>已自动取得的证据与下一步</summary><ul>'
  foreach($proof in $c.Proof){$card+='<li>'+(E $proof)+'</li>'};$card+='</ul>'
  foreach($f in $c.Files){$card+='<dl>'+(Row '文件' $f.Path)+(Row '签名 / SHA256' ($f.Signature+' / '+$f.SHA256))+(Row '下载来源标记' $f.ZoneIdentifier)+'</dl>'}
  foreach($group in @($c.Connections|Group-Object Pid,RemoteAddress,RemotePort,State|Select-Object -First 12)){$conn=$group.Group[0];$card+='<p class="small">'+(E ('PID '+$conn.Pid+' → '+$conn.RemoteAddress+':'+$conn.RemotePort+'；'+$conn.State+'；本窗口记录 '+$group.Count+' 次，未据此认定成功连接'))+'</p>'}
  foreach($evt in $c.HistoryEvents){$card+='<p class="small">'+(E ((T $evt.TimeUtc)+' | '+$evt.Log+'#'+$evt.RecordId+' | EventID='+$evt.Id))+'</p><pre>'+(E (ConvertTo-Json $evt.Data -Depth 5))+'</pre>'}
  $card+='<p><b>下一步：</b>'+(E $c.Containment)+'</p><p><b>复查标准：</b>'+(E $c.ExitCriteria)+'</p><p class="small">'+(E ($c.MissingEvidence -join '；'))+'</p></details></article>'
  $allCards+=$card;if($viewFindings.Count -lt 8){$cards+=$card};$deep+=Section $c.Id $c.Id $c.Kind $card
  $viewFindings+=[pscustomobject]@{Id=$c.Id;Title=$c.Kind;Target=$c.Target;Description=($c.Trigger -join '；');Severity=$c.Severity}
  $mdCases+="`r`n### $($c.Id) $($c.Kind)`r`n`r`n对象：$($c.Target)`r`n依据：$($c.Trigger -join '；')`r`n状态：$($c.State)`r`n"
  foreach($s in $c.Persistence){$mdCases+="`r`n- $($s.Kind)：$($s.Location) [$($s.Name)] → $($s.Command)`r`n"}
  continue
 }
 if($c.Kind -eq '异常启动轨迹'){
  $t=$c.Timeline;$timeline=@([pscustomobject]@{Time=$t.Launch.TimeUtc;Text='系统启动历史记录此程序';Source='UserAssist'},[pscustomobject]@{Time=$t.Deletion.TimeUtc;Text=('原文件被删除，距启动 '+$t.DeleteAfterSeconds+' 秒');Source='NTFS USN，Reason=0x{0:X}' -f [uint32]$t.Deletion.Reason})
  foreach($cr in $t.Crashes){$timeline+=@([pscustomobject]@{Time=$cr.TimeUtc;Text=($cr.AppName+' 崩溃；故障模块 '+$cr.FaultModule+'；异常码 '+$cr.ExceptionCode);Source='Windows Error Reporting'})}
  $lines='<ol class="steps">';$mdLines=''
  foreach($step in $timeline|Sort-Object Time){$lines+='<li><div><b>'+(E (T $step.Time))+'</b><p>'+(E $step.Text)+'<br><span class="small">'+(E $step.Source)+'</span></p></div></li>';$mdLines+="`r`n- $(T $step.Time)：$($step.Text)（$($step.Source)）"};$lines+='</ol>'
