 if(!$netRows.Count){$networkHtml+='<p class="caution">未取得域名或远端地址。DNS缓存为空、日志未启用、观察窗口内未产生事件等情况都可能导致空结果，不能据此排除外连。</p>'}
 if($network.Pivots.Count){$networkHtml+='<h3>从通信进程继续定位</h3><p class="small">展开程序可核对同一实例的模块、内存和配置；这些引用不自动成为清理对象。</p>'}
 foreach($pivot in $network.Pivots){
  $networkHtml+='<details id="'+(E $pivot.Id)+'"><summary>'+(E ($pivot.Id+' · PID '+$pivot.Pid+' · '+[IO.Path]::GetFileName([string]$pivot.Path)))+'</summary><dl>'+(Row '程序完整路径' $pivot.Path)+(Row '进程启动UTC' $pivot.StartUtc)+(Row '命令行' $pivot.Command)+(Row '身份与证据' $pivot.Assessment)+'</dl>'
  if(!$pivot.CurrentIdentityMatched){$networkHtml+='<p>该观察期实例已不在当前进程清单，不能用当前同PID进程补齐模块或服务。</p>'}else{
   $networkHtml+='<h3>载荷 / 已加载模块</h3>'
   if(!$pivot.ModuleCandidates.Count){$networkHtml+='<p>取得 '+$pivot.LoadedModuleCount+' 个模块记录，尚未定位异常模块；部分文件可能未完成验证。</p>'}
   foreach($m in $pivot.ModuleCandidates){$networkHtml+='<dl>'+(Row '模块候选完整路径' $m.Path)+(Row '签名 / SHA256' ($m.Signature+' | '+$m.SHA256))+(Row '隐藏父目录' $m.HiddenParent)+'</dl>'}
   if($pivot.MemoryEvidence.Count){$networkHtml+='<details><summary>同一实例的内存异常候选</summary><pre>'+(E ($pivot.MemoryEvidence|ConvertTo-Json -Depth 7))+'</pre></details>'}
   $networkHtml+='<h3>注册表 / 服务 / 任务配置引用</h3>'
   if(!$pivot.ConfigurationReferences.Count){$networkHtml+='<p>未定位直接引用此程序或已加载模块的配置；没有据此指定清理位置。</p>'}
   foreach($c in $pivot.ConfigurationReferences){$networkHtml+='<dl>'+(Row '配置类型 / 名称' ($c.Kind+' | '+$c.Name))+(Row '完整位置' $c.Location)+(Row '目标 / 参数' ($c.Path+' | '+$c.Command))+(Row '启用 / 启动账号' ([string]$c.Enabled+' | '+$c.StartMode+' | '+$c.Principal))+'</dl>'}
   if($pivot.HostedServices.Count){$networkHtml+='<details><summary>该实例承载的 '+$pivot.HostedServices.Count+' 个服务（尚未确认哪项被利用）</summary>';foreach($s in $pivot.HostedServices){$networkHtml+='<dl>'+(Row '服务名 / 注册表位置' ($s.Name+' | '+$s.Location))+(Row '启动命令 / 账号' ($s.Command+' | '+$s.Principal))+'</dl>'};$networkHtml+='</details>'}
  }
  $networkHtml+='</details>'
 }
 foreach($r in $netRows|Select-Object -First 200){$networkHtml+='<div class="note-card"><b>'+(E ($r.Kind+' | '+$r.Value))+'</b><dl>'+(Row '进程 / PID' ($r.Process+' | '+$r.Pid))+(Row '归属依据' $r.Identity)+(Row '时间 / 次数' ($r.FirstUtc+' 至 '+$r.LastUtc+' | '+$r.Count))+(Row '来源' $r.Source)+(Row '事件细节' $r.Detail)+'</dl></div>'}
 $networkHtml+='<p class="small">页面最多展示200组；完整记录在 network-evidence.json，原始DNS事件在 evidence.json / ETL。</p><p>'+(E ($network.Observation.Notes -join '；'))+'</p><p>'+(E $network.Observation.Limit)+'</p><a href="network-evidence.json">完整网络证据 JSON</a>'
}
$cards+='<p class="small"><a href="network-evidence.html">'+(E $networkSummary)+' → 查看域名、IP、进程与采集缺口</a></p>'
$startupHtml='<p>没有取得符合条件的驻留目录追查组合；不能据此排除驻留。</p>'
$startupPivots=@($raw.General.PersistencePivots|Where-Object {$_})
if($startupPivots.Count){
 $startupHtml='<p>这些是自动取得的驻留引用和相邻DLL追查入口，未判定为木马。不存在隐藏属性或当前进程时，引用关系仍保留。</p>'
 foreach($s in $startupPivots){$startupHtml+='<article class="case"><dl>'+(Row '驻留启动目标' $s.HostPath)+(Row 'DLL完整路径' $s.Path)+(Row '签名 / SHA256' ($s.Signature+' | '+$s.SHA256))+(Row '关系与限制' $s.Assessment)+'</dl>';foreach($ref in $s.References){$startupHtml+='<dl>'+(Row '配置类型 / 名称' ($ref.Kind+' | '+$ref.Name))+(Row '完整位置' $ref.Location)+(Row '命令' $ref.Command)+'</dl>'};$startupHtml+='</article>'}
 $cards+='<p class="small"><a href="persistence-pivots.html">另有 '+$startupPivots.Count+' 组驻留加载目录追查入口（未认定恶意） →</a></p>'
}
$title=if($cases.Count){$assessmentLabel+' · '+$cases.Count+' 组异常'}elseif($assessmentLevel -eq 'green'){'本次检查未发现异常'}else{'未发现异常，检查存在缺口'}
$lead=if($assessmentLevel -eq 'red'){'优先核验下方高风险对象，保持主机隔离。'}elseif($cases.Count){'已定位可疑对象，请核对用途与证据。'}elseif($assessmentLevel -eq 'yellow'){'关键检查未完成，不能评为健康。'}else{'核心检查已完成；结论仅适用于本次检查范围。'}
$persistenceCount=@($cases.Persistence|Where-Object {$_}|ForEach-Object {$_.Kind+'|'+$_.Location+'|'+$_.Name}|Select-Object -Unique).Count
$addressCount=@($cases.NetworkEvidence|Where-Object Value|ForEach-Object {$_.Value}|Select-Object -Unique).Count
$headline='<div class="verdict '+$assessmentLevel+'" role="status"><div class="verdict-top"><div><span class="label">风险评估</span><h2>'+(E $assessmentLabel)+'</h2></div><span class="status-symbol" aria-hidden="true">'+$(if($assessmentLevel -eq 'green'){'✓'}else{'!'})+'</span></div><p>'+(E $lead)+'</p><div class="metrics"><div><strong>'+$cases.Count+'</strong><span>异常对象</span></div><div><strong>'+$persistenceCount+'</strong><span>关联持久化</span></div><div><strong>'+$addressCount+'</strong><span>外联地址线索</span></div></div></div>'
if($materialGaps.Count){$headline+='<p class="coverage-note"><a href="#gaps">'+$materialGaps.Count+' 项检查缺口</a> · 详见检查范围</p>'}
$nextHtml=if($cases.Count){'<p class="action-strip">保持隔离 → 保全文件与配置 → 核验异常 → 人工处置 → 复查。</p>'}elseif($materialGaps.Count){'<p class="action-strip">补齐检查缺口后复查；异常持续时扩大取证范围。</p>'}else{'<p class="action-strip">保留报告；出现新告警或异常后重新检查。</p>'}
$closing='<p>'+(E $title)+'。本次仅检查与取证，未执行系统处置。</p><div class="links"><a href="evidence.json">原始证据</a><a href="analysis.json">完整分析</a><a href="manifest.json">文件校验</a><a href="report.md">文字版</a></div>'
$css=@'
:root{--ink:#183044;--muted:#667b8b;--line:#e1e9ed;--blue:#087f8c;--bg:#f4f7f9}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.65 "Segoe UI","Microsoft YaHei",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}a:focus-visible,summary:focus-visible,button:focus-visible{outline:3px solid #168d98;outline-offset:4px}main{max-width:1060px;margin:30px auto;padding:0 26px}header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px 28px;background:#183044;color:white;border-radius:16px 16px 0 0}.brand{display:flex;align-items:center;gap:14px;font-weight:700;font-size:18px}.brand img{width:54px;height:54px;border-radius:0;background:transparent;object-fit:contain}.brand small{display:block;font-size:11px;color:#c1d0d9;font-weight:400;margin-top:3px;letter-spacing:1px}button{font:inherit;border:1px solid #6d8799;background:transparent;border-radius:8px;padding:8px 14px;color:white;cursor:pointer}.paper{background:white;border:1px solid var(--line);border-top:0;border-radius:0 0 16px 16px;overflow:hidden;box-shadow:0 10px 32px #18304406}.cover{padding:25px 30px 20px}h1{margin:0 0 6px;font-size:27px;letter-spacing:-.5px}.meta,.small{font-size:12px;color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:8px 24px;margin:18px 0 0;font-size:12px}nav b{font-weight:400;color:#8294a0;margin-right:6px}section{padding:24px 30px;border-top:1px solid var(--line)}h2{font-size:17px;margin:0 0 16px}h2>span{font:11px Consolas;color:#8195a3;margin-right:10px}h3{font-size:14px;margin:0 0 8px}p{margin:8px 0}.verdict{--tone:#a66b00;--wash:#fff8e9;color:var(--tone);padding:22px 24px;background:var(--wash);border:1px solid color-mix(in srgb,var(--tone) 18%,white);border-radius:12px}.red{--tone:#c83a43;--wash:#fff1f2}.yellow{--tone:#a66b00;--wash:#fff8e9}.green{--tone:#16805c;--wash:#eef9f3}.verdict-top{display:flex;justify-content:space-between;align-items:center}.verdict h2{font-size:27px;line-height:1.4;margin:4px 0 10px;color:var(--tone)}.verdict p{font-size:13px;margin:0}.label{font-size:11px;letter-spacing:1px}.status-symbol{width:40px;height:40px;border:2px solid var(--tone);border-radius:50%;display:grid;place-items:center;font-size:27px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:20px}.metrics>div{display:flex;align-items:baseline;gap:14px;background:#ffffffbd;border:1px solid #ffffff;border-radius:9px;padding:14px 18px}.metrics strong{font:600 30px/1.2 "Segoe UI",sans-serif;color:var(--tone)}.metrics span{font-size:12px;color:var(--ink)}.coverage-note{font-size:12px;color:var(--muted);margin:12px 0 0}.case,.note-card{border:1px solid var(--line);border-radius:10px;padding:19px 20px;margin:12px 0;overflow-wrap:anywhere}.note-card{background:#f7fafb}.case-title{display:flex;align-items:center;gap:10px}.case-title h3{flex:1;margin:0;min-width:0}.case-id{font:11px Consolas;color:#768995}.risk-tag{font-size:11px;background:var(--wash);color:var(--tone);padding:3px 9px;border-radius:5px;white-space:nowrap}.badge,.priority{font-size:11px;color:#a66b00;background:#fff8e9;padding:3px 8px;border-radius:5px}.row{display:grid;grid-template-columns:120px minmax(0,1fr);gap:16px;padding:7px 0;border-bottom:1px solid #f0f4f6;font-size:12px}.row:last-child{border-bottom:0}.row dt{color:var(--muted)}.row dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap;font-family:Consolas,"Microsoft YaHei",monospace}dl{margin:12px 0}.case>details{margin:14px 0}.action-link{font-size:12px}.compact-case{padding:0}.compact-case>summary{padding:16px 20px;list-style:none;position:relative;padding-right:44px}.compact-case>summary::-webkit-details-marker{display:none}.compact-case>summary:after{content:'+';position:absolute;right:19px;top:17px;color:var(--blue);font-size:18px}.compact-case[open]>summary:after{content:'−'}.compact-case>dl,.compact-case>details{margin-left:20px;margin-right:20px}.compact-case>.action-link{display:block;margin:0 20px 18px}.target-preview{display:block;font:11px/1.5 Consolas,"Microsoft YaHei",monospace;color:var(--muted);margin:8px 0 0 33px;overflow-wrap:anywhere}.empty{padding:20px;color:var(--muted);background:#f7fafb;border-radius:10px}.action-strip{background:#f3f8f9;padding:15px 18px;border-radius:8px;font-size:13px}.gap-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 25px}.gap-grid b{font-size:12px}.gap-grid p,.gap-grid span{font-size:12px;color:var(--muted)}details{margin:12px 0}summary{font-size:12px;color:var(--blue);cursor:pointer}pre{padding:15px;background:#f1f5f8;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 Consolas,"Microsoft YaHei",monospace}code{overflow-wrap:anywhere}.links{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;margin-top:14px}.caution,.sample{background:#fff8e9;padding:14px;border-radius:8px;font-size:12px;overflow-wrap:anywhere}.sample{margin:12px 0}.footer{color:#768b99;font-size:11px;display:flex;justify-content:space-between;gap:12px;margin:16px 0 25px}.detail h3{margin-top:20px}.detail p{overflow-wrap:anywhere}.plain,.steps{font-size:12px}.subhead{margin-top:22px}@media(max-width:640px){main{padding:0 12px;margin-top:12px}header{padding:16px;gap:10px}.brand{font-size:14px;gap:10px}.brand img{width:40px;height:40px}.brand small{font-size:9px}header button{font-size:10px;padding:6px 8px}.cover,section{padding:20px 16px}h1{font-size:23px}.verdict{padding:18px 16px}.verdict h2{font-size:24px}.metrics{gap:7px}.metrics>div{padding:10px 7px;display:block}.metrics strong{font-size:26px;display:block}.metrics span{font-size:10px}nav{gap:8px 14px}.gap-grid{grid-template-columns:1fr}.row{grid-template-columns:1fr;gap:3px}.case,.note-card{padding:16px}.compact-case{padding:0}.compact-case>summary{padding-left:16px}.case-title h3{font-size:13px}.footer{flex-direction:column}.links{gap:12px}}@page{size:A4;margin:15mm}@media print{body{background:white;font-size:10pt}main{max-width:none;margin:0;padding:0}header button{display:none}header{-webkit-print-color-adjust:exact;print-color-adjust:exact}.paper{border:0;box-shadow:none}.cover,section{padding:15px 0}h1{font-size:23px}h2{font-size:15px}.verdict{padding:15px}.case,.note-card,.metrics{break-inside:avoid}.footer{display:none}.verdict,.risk-tag{-webkit-print-color-adjust:exact;print-color-adjust:exact}details:not([open]){display:none}.compact-case:not([open]){display:block}.compact-case:not([open])>*:not(summary){display:none}}
'@
$brandLogo='data:image/png;base64,'
function Document($heading,$body,$isMain=$false){
 $sampleHtml=if($sample){'<div class="sample">合成示例 · 所有对象、地址和哈希均为构造数据，不是本机感染结果。</div>'}else{''}
 $nav=if($isMain){'<nav aria-label="报告目录"><a href="#summary"><b>01</b>概要</a><a href="#findings"><b>02</b>实际发现</a><a href="#actions"><b>03</b>处置建议</a><a href="#gaps"><b>04</b>检查范围</a><a href="#conclusion"><b>05</b>总结</a></nav>'}else{'<nav><a href="report.html">← 返回简报</a></nav>'}
 '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+(E $heading)+' · '+(E $raw.Host.Computer)+'</title><style>'+$css+'</style></head><body><main><header><div class="brand"><img alt="问渠安全实验室 Logo" src="'+$brandLogo+'"><div>问渠安全实验室<small>应急·轻 / WINDOWS 1.13</small></div></div><button onclick="window.print()">打印 / 保存 PDF</button></header>'+$sampleHtml+'<div class="paper"><div class="cover"><h1>'+(E $heading)+'</h1><div class="meta">主机 '+(E $raw.Host.Computer)+' · 采集时间 '+(E $stamp)+' UTC+8</div>'+$nav+'</div>'+$body+'</div><div class="footer"><span>问渠安全实验室 出品</span><span>本地取证 · 分享前脱敏</span></div></main></body></html>'
}
$body=(Section 'summary' '01' '概要' $headline)+(Section 'findings' '02' '实际发现' $cards)+(Section 'actions' '03' '处置建议' $nextHtml)+(Section 'gaps' '04' '检查范围' ('<details><summary>检查缺口与覆盖范围</summary><p class="small">'+(E ($materialGaps -join '；'))+'</p>'+$gapDetails+'</details>'))+(Section 'conclusion' '05' '总结与证据' $closing)
SaveText 'network-evidence.html' (Document '独立网络证据' ('<section>'+$networkHtml+'</section>'))
SaveText 'persistence-pivots.html' (Document '驻留加载目录追查' ('<section>'+$startupHtml+'</section>'))
SaveText 'report.html' (Document '应急排查报告' $body $true)
if(!$deep){$deep='<section><p>本次没有生成需核验的攻击对象。先按简报中的下一步补充采集。</p></section>'}
if($diagnostics.Count){$deep+=(Section 'diagnostics' '备注' '核查备注与查询命令' $diagnosticDetails)}
SaveText 'response-plan.html' (Document '对象证据与核验步骤' ('<div class="detail">'+$deep+'</div>'))
SaveText 'findings-detail.html' (Document '全部待核查对象' ('<section>'+$(if($allCards){$allCards}else{'没有待核查攻击对象。'})+'</section>'))
$md=@"
# 应急排查报告

问渠安全实验室 出品

主机：$($raw.Host.Computer) · 采集：$stamp UTC+8 · 研判版本：1.13

$(if($sample){'**合成示例：所有数据均为构造，不是本机感染结果。**'})

目录：[概要](#概要) · [实际发现](#实际发现) · [下一步](#下一步) · [检查盲区](#检查盲区) · [总结与证据](#总结与证据)

## 概要

**$title**。$lead

## 实际发现

$(if(!$cases.Count){'未能确定攻击入口、恶意落地文件或权限维持手段。'})
$mdCases
$mdDiag
## 下一步
$(if($cases.Count){'保持隔离 → 保全文件与配置 → 核验异常 → 人工处置 → 复查。'}elseif($materialGaps.Count){'补齐检查缺口后复查。'}else{'保留报告，出现新异常时重新检查。'})
## 检查盲区
$(if($materialGaps.Count){$materialGaps -join '；'}else{'核心检查已完成；结论仅适用于本次检查范围。'})

完整覆盖范围见 HTML 报告的展开项及 analysis.json。
## 总结与证据

$title。本次仅检查与取证，未执行系统处置。

[对象核验](response-plan.html) · [原始证据](evidence.json) · [完整分析](analysis.json) · [校验清单](manifest.json)
"@
SaveText 'report.md' $md
$v=[pscustomobject]@{Version='1.13';Brand='问渠安全实验室';AssessmentLevel=$assessmentLevel;AssessmentLabel=$assessmentLabel;AssessmentColor=$assessmentColor;AssessmentBasis=$lead;MaterialGaps=$materialGaps.ToArray();Status=$title;IssueCount=$cases.Count;PriorityCount=$severeCases.Count;DisplayedCount=$cases.Count;Findings=$viewFindings;DiagnosticCount=$diagnostics.Count;Limitations=$gaps.ToArray();Summary=$lead;NextSteps=$next.ToArray()}
SaveText 'report-view.json' (ConvertTo-Json $v -Depth 10)

SaveText 'scan-summary.txt' $title
